import java.util.*;
class Employee { int basic; Employee(int b){basic=b;} }
class Manager extends Employee { int bonus; Manager(int b,int x){super(b);bonus=x;} int total(){return basic+bonus;} }
public class Main { public static void main(String[] args){ Scanner sc=new Scanner(System.in); int b=sc.nextInt(),x=sc.nextInt(); System.out.println(new Manager(b,x).total()); } }

import java.util.*;
class Shape { int area(){return 0;} }
class Rectangle extends Shape { int l,w; Rectangle(int a,int b){l=a;w=b;} @Override int area(){return l*w;} }
public class Main { public static void main(String[] args){ Scanner sc=new Scanner(System.in); System.out.println(new Rectangle(sc.nextInt(),sc.nextInt()).area()); } }

